using namespace std;

int main() {
    int n;
    if(!(cin >> n)) return 0;
    // Kiểm tra giới hạn (không bắt buộc nhưng an toàn)
    if(n < 0) n = 0;
    if(n > 100) n = 100;
    int i = 1;
    long long sum = 0;
    while(i <= n) {
        sum += i;
        ++i;
    }
    cout << sum << "\n";
    return 0;
}

